@page "/apply"
@rendermode InteractiveServer
@using sv_5b3d18092a6540809a5a80e390bfab2b.Models
@using sv_5b3d18092a6540809a5a80e390bfab2b.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var status = GetStepStatus(stepIndex);
        <button class="step @status"
                disabled="@(status == "future")"
                @onclick="() => GoToStep(stepIndex)">
            @if (status == "completed")
            {
                <span class="step-icon">&#10003;</span>
            }
            else
            {
                <span class="step-number">@(stepIndex + 1)</span>
            }
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (stepIndex < StepNames.Length - 1)
        {
            <span class="step-connector"></span>
        }
    }
</nav>

@* Step Content *@
<div class="step-content">
    @if (_submitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your application ID is: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        @switch (_currentStep)
        {
            case 0:
                @RenderPersonalInfo();
                break;
            case 1:
                @RenderWorkHistory();
                break;
            case 2:
                @RenderReferences();
                break;
            case 3:
                @RenderCoverLetter();
                break;
            case 4:
                @RenderReview();
                break;
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="error-message">@_errorMessage</div>
}

