{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_5b3d18092a6540809a5a80e390bfab2b.Models
@using sv_5b3d18092a6540809a5a80e390bfab2b.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var status = GetStepStatus(stepIndex);
        <button class="step @status"
                disabled="@(status == "future")"
                @onclick="() => GoToStep(stepIndex)">
            @if (status == "completed")
            {
                <span class="step-icon">&#10003;</span>
            }
            else
            {
                <span class="step-number">@(stepIndex + 1)</span>
            }
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (stepIndex < StepNames.Length - 1)
        {
            <span class="step-connector"></span>
        }
    }
</nav>

@* Step Content *@
<div class="step-content">
    @if (_submitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your application ID is: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        @switch (_currentStep)
        {
            case 0:
                @RenderPersonalInfo();
                break;
            case 1:
                @RenderWorkHistory();
                break;
            case 2:
                @RenderReferences();
                break;
            case 3:
                @RenderCoverLetter();
                break;
            case 4:
                @RenderReview();
                break;
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="error-message">@_errorMessage</div>
}

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private const int MaxCoverLetterLength = 2000;

    private int _currentStep;
    private int _highestCompletedStep = -1;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;
    private bool _isProcessing;

    // Step 1 - Personal Info
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 - Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 - References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 - Cover Letter
    private string _coverLetter = "";

    private string GetStepStatus(int step)
    {
        if (step == _currentStep) return "active";
        if (step <= _highestCompletedStep) return "completed";
        return "future";
    }

    private void GoToStep(int step)
    {
        if (step <= _highestCompletedStep)
        {
            _currentStep = step;
            _errorMessage = null;
        }
    }

    private async Task NextStep()
    {
        _errorMessage = null;
        _isProcessing = true;

        try
        {
            if (!await ValidateCurrentStep()) return;

            if (_currentStep > _highestCompletedStep)
                _highestCompletedStep = _currentStep;

            _currentStep++;
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = null;
        }
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName))
                { _errorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(_email))
                { _errorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(_phone))
                { _errorMessage = "Phone is required."; return false; }
                if (string.IsNullOrWhiteSpace(_address))
                { _errorMessage = "Address is required."; return false; }

                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                if (!emailValid)
                { _errorMessage = "Please enter a valid email address."; return false; }
                break;

            case 1:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                    { _errorMessage = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                    { _errorMessage = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                    { _errorMessage = "Start date is required for all entries."; return false; }
                }
                break;

            case 2:
                foreach (var reference in _references)
                {
                    if (string.IsNullOrWhiteSpace(reference.Name))
                    { _errorMessage = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(reference.Relationship))
                    { _errorMessage = "Relationship is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(reference.Email))
                    { _errorMessage = "Email is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(reference.Phone))
                    { _errorMessage = "Phone is required for all references."; return false; }
                }
                break;

            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                { _errorMessage = "Cover letter is required."; return false; }
                if (_coverLetter.Length > MaxCoverLetterLength)
                { _errorMessage = $"Cover letter must not exceed {MaxCoverLetterLength} characters."; return false; }
                break;
        }
        return true;
    }

    private async Task SubmitApplication()
    {
        _errorMessage = null;
        _isProcessing = true;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(WorkEntryModel entry)
    {
        if (_workEntries.Count > 1)
            _workEntries.Remove(entry);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(ReferenceModel reference)
    {
        if (_references.Count > 2)
            _references.Remove(reference);
    }

