                    <input type="email" @bind="reference.Email" placeholder="Reference email" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" @bind="reference.Phone" placeholder="Reference phone" />
                </div>
                @if (_references.Count > 2)
                {
                    <button class="btn-remove" @onclick="() => RemoveReference(reference)">Remove</button>
                }
            </fieldset>
        }
        @if (_references.Count < 3)
        {
            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep" disabled="@_isProcessing">Next</button>
        </div>
    };

    private RenderFragment RenderCoverLetter() => __builder =>
    {
        <h2>Cover Letter</h2>
        <div class="form-group">
            <label for="coverLetter">Write your cover letter *</label>
            <textarea id="coverLetter" class="cover-letter-input" @bind="_coverLetter"
                      placeholder="Tell us why you're a great fit for this role..."></textarea>
            <div class="char-count @(_coverLetter.Length > MaxCoverLetterLength ? "over-limit" : "")">
                @_coverLetter.Length / @MaxCoverLetterLength characters
            </div>
        </div>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep" disabled="@_isProcessing">Next</button>
        </div>
    };

    private RenderFragment RenderReview() => __builder =>
    {
        <h2>Review & Submit</h2>

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@_fullName</dd>
                <dt>Email</dt><dd>@_email</dd>
                <dt>Phone</dt><dd>@_phone</dd>
                <dt>Address</dt><dd>@_address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
            </div>
            @foreach (var entry in _workEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                    <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
            </div>
            @foreach (var reference in _references)
            {
                <div class="review-entry">
                    <strong>@reference.Name</strong> (@reference.Relationship)<br />
                    <span>@reference.Email | @reference.Phone</span>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@_coverLetter</p>
        </section>

        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isProcessing">
                @(_isProcessing ? "Submitting..." : "Submit Application")
            </button>
        </div>
    };
}
