+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+
+    // Render fragments
+    private RenderFragment RenderPersonalInfo() => __builder =>
+    {
+        <h2>Personal Information</h2>
+        <div class="form-group">
+            <label for="fullName">Full Name *</label>
+            <input id="fullName" type="text" @bind="_fullName" placeholder="Enter your full name" />
+        </div>
+        <div class="form-group">
+            <label for="email">Email *</label>
+            <input id="email" type="email" @bind="_email" placeholder="Enter your email" />
+        </div>
+        <div class="form-group">
+            <label for="phone">Phone *</label>
+            <input id="phone" type="tel" @bind="_phone" placeholder="Enter your phone number" />
+        </div>
+        <div class="form-group">
+            <label for="address">Address *</label>
+            <input id="address" type="text" @bind="_address" placeholder="Enter your address" />
+        </div>
+        <div class="form-buttons">
+            <button class="btn-next" @onclick="NextStep" disabled="@_isProcessing">
+                @(_isProcessing ? "Validating..." : "Next")
+            </button>
+        </div>
+    };
+
+    private RenderFragment RenderWorkHistory() => __builder =>
+    {
+        <h2>Work History</h2>
+        @for (int i = 0; i < _workEntries.Count; i++)
+        {
+            var entry = _workEntries[i];
+            var index = i;
+            <fieldset class="work-entry">
+                <legend>Position @(index + 1)</legend>
+                <div class="form-group">
+                    <label>Company *</label>
+                    <input type="text" @bind="entry.Company" placeholder="Company name" />
+                </div>
+                <div class="form-group">
+                    <label>Job Title *</label>
+                    <input type="text" @bind="entry.Title" placeholder="Job title" />
+                </div>
+                <div class="form-row">
+                    <div class="form-group">
+                        <label>Start Date *</label>
+                        <input type="date" @bind="entry.StartDate" />
+                    </div>
+                    <div class="form-group">
+                        <label>End Date</label>
+                        <input type="date" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
+                    </div>
+                    <div class="form-group checkbox-group">
+                        <label>
+                            <input type="checkbox" @bind="entry.IsCurrent" />
+                            Current position
+                        </label>
+                    </div>
+                </div>
+                <div class="form-group">
+                    <label>Description</label>
+                    <textarea @bind="entry.Description" placeholder="Describe your responsibilities..."></textarea>
+                </div>
+                @if (_workEntries.Count > 1)
+                {
+                    <button class="btn-remove" @onclick="() => RemoveWorkEntry(entry)">Remove</button>
+                }
+            </fieldset>
+        }
+        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
+        <div class="form-buttons">
+            <button class="btn-back" @onclick="PreviousStep">Back</button>
+            <button class="btn-next" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+        </div>
+    };
+
+    private RenderFragment RenderReferences() => __builder =>
+    {
+        <h2>References</h2>
+        @for (int i = 0; i < _references.Count; i++)
+        {
+            var reference = _references[i];
+            var index = i;
+            <fieldset class="reference-entry">
+                <legend>Reference @(index + 1)</legend>
+                <div class="form-group">
+                    <label>Name *</label>
+                    <input type="text" @bind="reference.Name" placeholder="Reference name" />
+                </div>
+                <div class="form-group">
+                    <label>Relationship *</label>
+                    <input type="text" @bind="reference.Relationship" placeholder="e.g., Former Manager" />
+                </div>
+                <div class="form-group">
+                    <label>Email *</label>
+                    <input type="email" @bind="reference.Email" placeholder="Reference email" />
+                </div>
+                <div class="form-group">
+                    <label>Phone *</label>
+                    <input type="tel" @bind="reference.Phone" placeholder="Reference phone" />
+                </div>
+                @if (_references.Count > 2)
+                {
+                    <button class="btn-remove" @onclick="() => RemoveReference(reference)">Remove</button>
+                }
+            </fieldset>
+        }
+        @if (_references.Count < 3)
+        {
+            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
+        }
+        <div class="form-buttons">
+            <button class="btn-back" @onclick="PreviousStep">Back</button>
+            <button class="btn-next" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+        </div>
+    };
+
+    private RenderFragment RenderCoverLetter() => __builder =>
+    {
+        <h2>Cover Letter</h2>
+        <div class="form-group">
+            <label for="coverLetter">Write your cover letter *</label>
+            <textarea id="coverLetter" class="cover-letter-input" @bind="_coverLetter"
+                      placeholder="Tell us why you're a great fit for this role..."></textarea>
+            <div class="char-count @(_coverLetter.Length > MaxCoverLetterLength ? "over-limit" : "")">
+                @_coverLetter.Length / @MaxCoverLetterLength characters
+            </div>
+        </div>
+        <div class="form-buttons">
+            <button class="btn-back" @onclick="PreviousStep">Back</button>
+            <button class="btn-next" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+        </div>
+    };
+
+    private RenderFragment RenderReview() => __builder =>
+    {
+        <h2>Review & Submit</h2>
+
+        <section class="review-section">
+            <div class="review-header">
+                <h3>Personal Information</h3>
+                <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
+            </div>
+            <dl>
+                <dt>Full Name</dt><dd>@_fullName</dd>
+                <dt>Email</dt><dd>@_email</dd>
+                <dt>Phone</dt><dd>@_phone</dd>
+                <dt>Address</dt><dd>@_address</dd>
+            </dl>
+        </section>
+
+        <section class="review-section">
+            <div class="review-header">
+                <h3>Work History</h3>
+                <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
+            </div>
+            @foreach (var entry in _workEntries)
+            {
+                <div class="review-entry">
+                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                    <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
+                    @if (!string.IsNullOrWhiteSpace(entry.Description))
+                    {
+                        <p>@entry.Description</p>
+                    }
+                </div>
+            }
+        </section>
+
+        <section class="review-section">
+            <div class="review-header">
+                <h3>References</h3>
+                <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
+            </div>
+            @foreach (var reference in _references)
+            {
+                <div class="review-entry">
+                    <strong>@reference.Name</strong> (@reference.Relationship)<br />
+                    <span>@reference.Email | @reference.Phone</span>
+                </div>
+            }
+        </section>
+
+        <section class="review-section">
+            <div class="review-header">
+                <h3>Cover Letter</h3>
+                <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
+            </div>
+            <p class="cover-letter-preview">@_coverLetter</p>
+        </section>
+
+        <div class="form-buttons">
+            <button class="btn-back" @onclick="PreviousStep">Back</button>
+            <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isProcessing">
+                @(_isProcessing ? "Submitting..." : "Submit Application")
+            </button>
+        </div>
+    };
+}
+

toolArgs.file_text:
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.25rem;
    margin: 1.5rem 0;
    flex-wrap: wrap;
}

.step-indicator .step {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.5rem 1rem;
    border: 2px solid #ccc;
    border-radius: 2rem;
    background: #f9f9f9;
    cursor: default;
    font-size: 0.9rem;
    transition: all 0.2s;
}

.step-indicator .step.active {
    border-color: #0d6efd;
    background: #e7f1ff;
    font-weight: 600;
}

.step-indicator .step.completed {
    border-color: #198754;
    background: #d1e7dd;
    cursor: pointer;
}

.step-indicator .step.future {
    opacity: 0.5;
}

.step-indicator .step-connector {
    width: 1.5rem;
    height: 2px;
    background: #ccc;
}

.step-icon {
    color: #198754;
    font-weight: bold;
}

.step-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 50%;
    background: #6c757d;
    color: white;
    font-size: 0.75rem;
}

.step.active .step-number {
    background: #0d6efd;
}

.step-content {
    max-width: 700px;
    margin: 1rem auto;
    padding: 1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    background: #fff;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.cover-letter-input {
    min-height: 200px !important;
}

.form-row {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.form-row .form-group {
    flex: 1;
    min-width: 150px;
}

.checkbox-group {
    display: flex;
    align-items: flex-end;
    padding-bottom: 0.5rem;
}

.checkbox-group label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal;
}

.form-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 1rem;
}

.btn-next, .btn-back, .btn-submit, .btn-add, .btn-remove, .btn-edit {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    cursor: pointer;
    transition: opacity 0.2s;
}

.btn-next {
    background: #0d6efd;
    color: white;
    margin-left: auto;
}

.btn-back {
    background: #6c757d;
    color: white;
}

.btn-submit {
    background: #198754;
    color: white;
    margin-left: auto;
}

.btn-add {
    background: #f8f9fa;
    border: 1px dashed #6c757d;
    color: #6c757d;
    margin-top: 0.5rem;
}

.btn-remove {
    background: #dc3545;
    color: white;
    font-size: 0.85rem;
    padding: 0.3rem 0.75rem;
}

.btn-edit {
    background: transparent;
    color: #0d6efd;
    text-decoration: underline;
    padding: 0.25rem 0.5rem;
}

button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

fieldset.work-entry,
fieldset.reference-entry {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

fieldset legend {
    font-weight: 600;
    padding: 0 0.5rem;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #dc3545;
    font-weight: 600;
}

.error-message {
    max-width: 700px;
    margin: 1rem auto;
    padding: 0.75rem 1rem;
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
    border-radius: 0.375rem;
}

.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h3 {
    margin: 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0.5rem 0;
}

.review-section dt {
    font-weight: 600;
    color: #6c757d;
}

.review-entry {
    margin: 0.5rem 0;
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 0.25rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 0.25rem;
}

.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h2 {
    color: #198754;
}

