+.form-group input[type="tel"],
+.form-group input[type="date"],
+.form-group textarea {
+    width: 100%;
+    padding: 0.5rem;
+    border: 1px solid #ced4da;
+    border-radius: 0.375rem;
+    font-size: 1rem;
+    box-sizing: border-box;
+}
+
+.form-group textarea {
+    min-height: 80px;
+    resize: vertical;
+}
+
+.cover-letter-input {
+    min-height: 200px !important;
+}
+
+.form-row {
+    display: flex;
+    gap: 1rem;
+    flex-wrap: wrap;
+}
+
+.form-row .form-group {
+    flex: 1;
+    min-width: 150px;
+}
+
+.checkbox-group {
+    display: flex;
+    align-items: flex-end;
+    padding-bottom: 0.5rem;
+}
+
+.checkbox-group label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    font-weight: normal;
+}
+
+.form-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 1.5rem;
+    gap: 1rem;
+}
+
+.btn-next, .btn-back, .btn-submit, .btn-add, .btn-remove, .btn-edit {
+    padding: 0.5rem 1.25rem;
+    border: none;
+    border-radius: 0.375rem;
+    font-size: 0.95rem;
+    cursor: pointer;
+    transition: opacity 0.2s;
+}
+
+.btn-next {
+    background: #0d6efd;
+    color: white;
+    margin-left: auto;
+}
+
+.btn-back {
+    background: #6c757d;
+    color: white;
+}
+
+.btn-submit {
+    background: #198754;
+    color: white;
+    margin-left: auto;
+}
+
+.btn-add {
+    background: #f8f9fa;
+    border: 1px dashed #6c757d;
+    color: #6c757d;
+    margin-top: 0.5rem;
+}
+
+.btn-remove {
+    background: #dc3545;
+    color: white;
+    font-size: 0.85rem;
+    padding: 0.3rem 0.75rem;
+}
+
+.btn-edit {
+    background: transparent;
+    color: #0d6efd;
+    text-decoration: underline;
+    padding: 0.25rem 0.5rem;
+}
+
+button:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+fieldset.work-entry,
+fieldset.reference-entry {
+    border: 1px solid #dee2e6;
+    border-radius: 0.5rem;
+    padding: 1rem;
+    margin-bottom: 1rem;
+}
+
+fieldset legend {
+    font-weight: 600;
+    padding: 0 0.5rem;
+}
+
+.char-count {
+    text-align: right;
+    font-size: 0.85rem;
+    color: #6c757d;
+    margin-top: 0.25rem;
+}
+
+.char-count.over-limit {
+    color: #dc3545;
+    font-weight: 600;
+}
+
+.error-message {
+    max-width: 700px;
+    margin: 1rem auto;
+    padding: 0.75rem 1rem;
+    background: #f8d7da;
+    color: #842029;
+    border: 1px solid #f5c2c7;
+    border-radius: 0.375rem;
+}
+
+.review-section {
+    margin-bottom: 1.5rem;
+    padding-bottom: 1rem;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+}
+
+.review-header h3 {
+    margin: 0;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0.5rem 0;
+}
+
+.review-section dt {
+    font-weight: 600;
+    color: #6c757d;
+}
+
+.review-entry {
+    margin: 0.5rem 0;
+    padding: 0.5rem;
+    background: #f8f9fa;
+    border-radius: 0.25rem;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 0.75rem;
+    border-radius: 0.25rem;
+}
+
+.confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.confirmation h2 {
+    color: #198754;
+}
+
